import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"豐","description":"周易正義 - 豐","frontmatter":{"title":"豐","description":"周易正義 - 豐"},"headers":[],"relativePath":"classics/zhengyi/055.md","filePath":"classics/zhengyi/055.md"}'),l={name:"classics/zhengyi/055.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>雷火豐</p></blockquote><blockquote><p>卦辭：亨，王假之；勿憂，宜日中。</p></blockquote><blockquote><p>彖曰：豐，大也。明以動，故豐。王假之，尚大也。勿憂宜日中，宜照天下也。日中則昃，月盈則食，天地盈虛，與時消息，而況於人乎，況於鬼神乎。</p></blockquote><h1 id="豐" tabindex="-1">豐 <a class="header-anchor" href="#豐" aria-label="Permalink to “豐”">​</a></h1><p>王弼：大而亨者，王之所至。</p><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“豐，亨”者，“豐”，卦名也，《彖》及《序卦。皆以“大”訓“豐”也，然則豐者，多大之名，盈足之義，財多德大，故謂之為豐。德大則無所不容，財多則無所不齊。無所擁礙謂之為“亨”，故曰“豐，亨”。“王假之”者，假，至也，豐亨之道，王之所尚，非有王者之德，不能至之，故曰“王假之”也。</p><h3 id="勿憂-宜日中。-​" tabindex="-1">勿憂，宜日中。 ​ <a class="header-anchor" href="#勿憂-宜日中。-​" aria-label="Permalink to “勿憂，宜日中。 ​”">​</a></h3><p>王弼：豐之為義，闡弘微細，通夫隱滯者也，為天下之主，而令微隱者不亨，憂未巳也，故至“豐亨”，乃得勿憂也。用夫豐亨不憂之德，宜處天中，以偏照者也，故曰“宜日中”也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：勿，無也。王能至於豐亨，乃得無復憂慮，故曰“勿憂也”。用夫豐亨無憂之德，然後可以君臨萬國，遍照四方，如日中之時，遍照天下，故曰“宜日中”也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="豐-大也。-​" tabindex="-1">豐，大也。 ​ <a class="header-anchor" href="#豐-大也。-​" aria-label="Permalink to “豐，大也。 ​”">​</a></h3><p>王弼：音闡大之大也。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>“彖曰：豐，大也”。○正義曰：“豐，大也”者，釋卦名，正是弘大之義也。○注“音闡大之大也”。○正義曰：闡者，弘廣之言，凡物之大，其有二種，一者自然之大，一者由人之闡弘使大。“豐”之為義，既闡弘微細，則豐之稱大，乃闡大之大，非自然之大，故音之也。</p><h3 id="明以動-故豐。王假之-尚大也。-​" tabindex="-1">明以動，故豐。王假之，尚大也。 ​ <a class="header-anchor" href="#明以動-故豐。王假之-尚大也。-​" aria-label="Permalink to “明以動，故豐。王假之，尚大也。 ​”">​</a></h3><p>王弼：大者王之所尚，故至之也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“動故豐”者，此就二體，釋卦得名，為豐之意，動而不明，未能光大資明以動，乃能致豐，故曰“明以動故豐”也。“王假之，尚大也”者，豐大之道，王所崇尚，所以王能至之，以能尚大故也。</p><h3 id="勿憂-宜日中-宜照天下也。-​" tabindex="-1">“勿憂，宜日中”，宜照天下也。 ​ <a class="header-anchor" href="#勿憂-宜日中-宜照天下也。-​" aria-label="Permalink to ““勿憂，宜日中”，宜照天下也。 ​”">​</a></h3><p>王弼：以勿憂之德，故宜照天下也。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：日中之時，遍照天下，王無憂慮，德乃光被，同於日中之盈，故曰“勿憂，宜日中，宜照天下也”。</p><h3 id="日中則昃-月盈則食-天地盈虛-與時消息-而況於人乎-況於鬼神乎-​" tabindex="-1">日中則昃，月盈則食，天地盈虛，與時消息，而況於人乎？況於鬼神乎？ ​ <a class="header-anchor" href="#日中則昃-月盈則食-天地盈虛-與時消息-而況於人乎-況於鬼神乎-​" aria-label="Permalink to “日中則昃，月盈則食，天地盈虛，與時消息，而況於人乎？況於鬼神乎？ ​”">​</a></h3><p>王弼：豐之為用，困於昃食者也。施於未足則尚豐，施於巳盈則方溢，不可以為常，故具陳消息之道者也。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：此孔子因豐設戒，以上言王者以豐大之德，照臨天下，同於日中。然盛必有衰，自然常理。日中至盛，過中則昃；月滿則盈，過盈則食。天之寒暑往來，地之陵谷遷貿，盈則與時而息，虛則與時而消。天地日月，尚不能久，況於人與鬼神，而能長保其盈盛乎？勉令及時脩德，仍戒居存慮亡也。此辭先陳天地，後言人、鬼、神者，欲以輕譬重，亦先尊後卑也。而日月先天地者，承上“宜日中”之下，遂言其昃食，因舉日月以對之，然後並陳天地，作文之體也。</p><h2 id="《象》曰-雷電皆至-豐。君子以折獄致刑。-​" tabindex="-1">《象》曰：雷電皆至，豐。君子以折獄致刑。 ​ <a class="header-anchor" href="#《象》曰-雷電皆至-豐。君子以折獄致刑。-​" aria-label="Permalink to “《象》曰：雷電皆至，豐。君子以折獄致刑。 ​”">​</a></h2><p>王弼：文明以動，不失情理也。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“雷電皆至，豐”者，雷者，天之威動，電者，天之光耀。雷電俱至，則威明備，足以為豐也。“君子以折獄致刑”者，君子法象天威而用刑罰，亦當文明以動，折獄斷決也。斷決獄訟，須得虛實之情；致用刑罰，必得輕重之中。若動而不明，則淫濫斯及，故君子象於此卦而折獄致刑。</p><h2 id="初九-遇其配主-雖旬無咎-往有尚。-​" tabindex="-1">初九：遇其配主，雖旬無咎，往有尚。 ​ <a class="header-anchor" href="#初九-遇其配主-雖旬無咎-往有尚。-​" aria-label="Permalink to “初九：遇其配主，雖旬無咎，往有尚。 ​”">​</a></h2><p>王弼：處豐之初，其配在四，以陽適陽，以明之動，能相光大者也。旬，均也。雖均無咎，往有尚也。初、四俱陽爻，故曰“均”也。</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“遇其配主”者，豐者，文明必動，尚乎光大者也。初配在四，俱是陽爻以陽適陽以明之動能相光大者，也。故曰：“遇其配主也。雖旬無咎往有尚者，旬均也，俱是陽爻，謂之為均，非是陰陽相應，嫌其有咎，以其能相光大，故雖均，可以無咎，而往有嘉尚也，故曰“雖均無咎，往有尚”也。</p><h3 id="《象》曰-雖旬無咎-過旬災也。-​" tabindex="-1">《象》曰：“雖旬無咎”，過旬災也。 ​ <a class="header-anchor" href="#《象》曰-雖旬無咎-過旬災也。-​" aria-label="Permalink to “《象》曰：“雖旬無咎”，過旬災也。 ​”">​</a></h3><p>王弼：過均則爭，交斯叛也。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>“象曰”至“災也”。○正義曰：“過旬災光”者，言勢若不均，則相傾奪。既相傾奪，則爭競乃興，而相違背，災咎至焉，故曰“過旬災也”。○注“過均”至“叛也”。○正義曰：初，四應配，謂之為交，勢若不均，則初、四之相交，於斯乖叛矣。</p><h2 id="六二-豐其蔀-日中見鬥。往得疑疾-有孚發若-吉。-​" tabindex="-1">六二：豐其蔀，日中見鬥。往得疑疾，有孚發若，吉。 ​ <a class="header-anchor" href="#六二-豐其蔀-日中見鬥。往得疑疾-有孚發若-吉。-​" aria-label="Permalink to “六二：豐其蔀，日中見鬥。往得疑疾，有孚發若，吉。 ​”">​</a></h2><p>王弼：蔀，覆曖，鄣光明之物也。處明動之時，不能自豐以光大之德，既處乎內，而又以陰居陰，所豐在蔀，幽而無睹者也，故曰“豐其蔀，日中見鬥”也。日中者，明之盛也；鬥見者，闇之極也。處盛明而豐其蔀，故曰“日中見鬥”。不能自發，故往得疑疾。然履中當位，處闇不邪，有孚者也。若，辭也。有孚可以發其志，不困於闇，故獲吉也。</p><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>“六二豐其蔀”至“有孚發若吉”。○正義曰：“豐其蔀”者，二以陰居遙又處於內，幽闇無所睹見，所豐在於覆蔽，故曰“豐其蔀”也。蔀者，覆曖，障光明之物也。“日中見鬥”者，二居離卦之中，如日正中，則至極盛者也。處日中盛明之時，而鬥星顯見，是二之至闇，使鬥星見明者也。處光大之世，而為極闇之行，譬日中而鬥星見，故曰“日中見鬥”也。二、五俱陰，二巳見鬥之闇，不能自發，以自求於五，往則得見疑之疾，故曰“往得疑疾”也。然居中履正，處闇不邪，是有信者也。有信以自發其志，不困於闇，故獲吉也。故曰“有孚發若，吉”也。</p><h3 id="《象》曰-有孚發若-信以發志也。-​" tabindex="-1">《象》曰：“有孚發若”，信以發志也。 ​ <a class="header-anchor" href="#《象》曰-有孚發若-信以發志也。-​" aria-label="Permalink to “《象》曰：“有孚發若”，信以發志也。 ​”">​</a></h3><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：信以發志者，雖處幽闇而不為邪，是有信以發其豐大之志，故得吉也。</p><h2 id="九三-豐其沛-日中見沬。折其右肱-無咎。-​" tabindex="-1">九三：豐其沛，日中見沬。折其右肱，無咎。 ​ <a class="header-anchor" href="#九三-豐其沛-日中見沬。折其右肱-無咎。-​" aria-label="Permalink to “九三：豐其沛，日中見沬。折其右肱，無咎。 ​”">​</a></h2><p>王弼：沛，幡幔，所以御盛光也。沬，微昧之明也。應在上六，志在乎陰，雖愈乎以陰處陰，亦未足以免於闇也。所豐在沛，日中則見沬之謂也。施明，則見沬而巳，施用，則折其右肱，故可以自守而巳，未足用也。</p><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“豐其沛，日中見沬”者，沛，幡幔，所以御盛光也。沬，微昧之明也，以九三應在上六，志在乎陰，雖愈於六二以陰處陰，亦未見免於闇也，是所以“豐在沛，日中見沬”。夫處光大之時，而豐沛見沬，雖愈於豐蔀見鬥，然施於大事，終不可用。假如折其右肱，自守而巳，乃得無咎，故曰“折其右肱，無咎”。</p><h3 id="《象》曰-豐其沛-不可大事也。-​" tabindex="-1">《象》曰：豐其沛，不可大事也。 ​ <a class="header-anchor" href="#《象》曰-豐其沛-不可大事也。-​" aria-label="Permalink to “《象》曰：豐其沛，不可大事也。 ​”">​</a></h3><p>王弼：明不足也。</p><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“不可大事”者，當光大之時，可為大事，明不足，故不可為大事也。</p><h3 id="折其右肱-終不可用也。-​" tabindex="-1">折其右肱，終不可用也。 ​ <a class="header-anchor" href="#折其右肱-終不可用也。-​" aria-label="Permalink to “折其右肱，終不可用也。 ​”">​</a></h3><p>王弼：雖有左在，不足用也。</p><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“終不可用”者，凡用事在右肱，右肱既折，雖有左在，終不可用也。</p><h2 id="九四-豐其蔀-日中見鬥。遇其夷主-吉。-​" tabindex="-1">九四：豐其蔀，日中見鬥。遇其夷主，吉。 ​ <a class="header-anchor" href="#九四-豐其蔀-日中見鬥。遇其夷主-吉。-​" aria-label="Permalink to “九四：豐其蔀，日中見鬥。遇其夷主，吉。 ​”">​</a></h2><p>王弼：以陽居陰，豐其蔀也。得初以發，夷主吉也。</p><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“豐其蔀”者，九四以陽居陰，闇同於六二，故曰“豐其蔀”也。“日中見鬥，遇其夷主，吉”者，夷，平也。四應在初，而同是陽爻，能相顯發，而得其吉，故曰“遇其夷主，吉”也。言四之與初交相為主者，若賓主之義也。若據初適四，則以四為主，故曰“遇其配主”。自四之初，則以初為主，故曰“遇其夷主”也。二陽體敵，兩主均平，故初謂四為“旬”，而四謂初為“夷”也。</p><h3 id="《象》曰-豐其蔀-位不當也。-日中見鬥-幽不明也。-遇其夷主-吉行也。-​" tabindex="-1">《象》曰：“豐其蔀”，位不當也。“日中見鬥”，幽不明也。“遇其夷主”，吉行也。 ​ <a class="header-anchor" href="#《象》曰-豐其蔀-位不當也。-日中見鬥-幽不明也。-遇其夷主-吉行也。-​" aria-label="Permalink to “《象》曰：“豐其蔀”，位不當也。“日中見鬥”，幽不明也。“遇其夷主”，吉行也。 ​”">​</a></h3><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“位不當”者，止謂以陽居陰，而位不當，所以豐蔀而闇者也。“幽不明也”者，日中盛則反而見鬥，以譬當光大而居陰，是應明而幽闇不明也。“吉行也”者，處於陰位，為闇巳甚，更應於陰，無由獲吉，猶與陽相遇，故得吉行也。</p><h2 id="六五-來章有慶譽-吉。-​" tabindex="-1">六五：來章有慶譽，吉。 ​ <a class="header-anchor" href="#六五-來章有慶譽-吉。-​" aria-label="Permalink to “六五：來章有慶譽，吉。 ​”">​</a></h2><p>王弼：以陰之質，來適尊陽之位，能自光大，章顯其德，獲慶譽也。</p><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：六五處豐大之世，以陰柔之質，來適尊陽之位，能自光大，章顯其德，而獲慶善也。故曰“來章有慶譽，吉”也。</p><h3 id="《象》曰-六五之吉-有慶也。-​" tabindex="-1">《象》曰：六五之吉，有慶也。 ​ <a class="header-anchor" href="#《象》曰-六五之吉-有慶也。-​" aria-label="Permalink to “《象》曰：六五之吉，有慶也。 ​”">​</a></h3><h3 id="疏-17" tabindex="-1">疏 <a class="header-anchor" href="#疏-17" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“有慶也”者，言六五以柔處尊，履得其中，故致慶譽也。</p><h2 id="上六-豐其屋-蔀其家-闚其戶-闃其無人。三歲不覿-兇。-​" tabindex="-1">上六：豐其屋，蔀其家，闚其戶，闃其無人。三歲不覿，兇。 ​ <a class="header-anchor" href="#上六-豐其屋-蔀其家-闚其戶-闃其無人。三歲不覿-兇。-​" aria-label="Permalink to “上六：豐其屋，蔀其家，闚其戶，闃其無人。三歲不覿，兇。 ​”">​</a></h2><p>王弼：屋，藏蔭之物，以陰處極而最在外，不履於位，深自幽隱，絕跡深藏者也。既豐其屋，又蔀其家，屋厚家覆，闇之甚也。雖闚其戶，闃其無人，棄其所處，而自深藏也。處於明動尚大之，時而深自幽隱，以高其行；大道既濟，而猶不見，隱不為賢，更為反道，兇其宜也。三年，豐道之成。治道未濟，隱猶可也；既濟而隱，是以治為亂者也。</p><h3 id="疏-18" tabindex="-1">疏 <a class="header-anchor" href="#疏-18" aria-label="Permalink to “疏”">​</a></h3><p>“上六豐其屋”至“不覿”。○正義曰：屋者，藏蔭隱蔽之物也。上六，以陰處陰，極以處外，不履於位，是深自幽隱，絕跡深藏也。事同豐厚於屋者也。既豐厚其屋，而又覆鄣其家，屋厚家闇，蔽鄣之甚也。雖闚視其戶，而闃寂無人，棄其所處，而自深藏也。處於豐大之世，隱不為賢。治道未濟，隱猶可也；三年豐道巳成，而猶不見，所以為兇，故曰“豐其屋，蔀其家，闚其戶，闃其無人，三歲不覿，兇”。</p><h3 id="《象》曰-豐其屋-天際翔也。-​" tabindex="-1">《象》曰：“豐其屋”，天際翔也。 ​ <a class="header-anchor" href="#《象》曰-豐其屋-天際翔也。-​" aria-label="Permalink to “《象》曰：“豐其屋”，天際翔也。 ​”">​</a></h3><p>王弼：翳光最甚者也。</p><h3 id="疏-19" tabindex="-1">疏 <a class="header-anchor" href="#疏-19" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“天祭翔也”者，如鳥之飛翔於天際，言隱翳之深也。</p><h3 id="闚其戶-闃其無人-自藏也。-​" tabindex="-1">“闚其戶，闃其無人”，自藏也。 ​ <a class="header-anchor" href="#闚其戶-闃其無人-自藏也。-​" aria-label="Permalink to ““闚其戶，闃其無人”，自藏也。 ​”">​</a></h3><p>王弼：可以出而不出，自藏之謂也，非有為而藏。不出戶庭，失時致兇，況自藏乎？兇其宜也。</p><h3 id="疏-20" tabindex="-1">疏 <a class="header-anchor" href="#疏-20" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“自藏也”者，言非有為而當自藏，可以出而不出，無事自為隱藏也。</p>',85)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
